   113	export function configureNginxDomains(content, domains) {
   114	  const frontendDomains = [...new Set([domains.mainDomain, domains.frontendDomain])].join(' ');
   115	  content = content.replace(/\n[ \t]*# API server\s*\([^)]*\)[\s\S]*?# End API server\n/, '\n');
   116	  const frontend = /(listen 8443 ssl;[\s\S]*?server_name\s+)[^;]+;/;
   117	  if (!frontend.test(content)) throw new Error('Frontend HTTPS virtual host not found');
   118	  content = content.replace(frontend, (_, prefix) => `${prefix}${frontendDomains};`);
   119	  const include = /^[ \t]*include \/etc\/nginx\/conf\.d\/\*\.conf;/m;
   120	  if (!include.test(content)) throw new Error('Nginx HTTP include not found');
   121	  const apiBlock = `${generateApiServerBlock(domains.backendDomain)}\n    # End API server\n`;
   122	  return content.replace(include, `${apiBlock}    include /etc/nginx/conf.d/*.conf;`);
   123	}
